require __DIR__.'/bootstrap.php';$number=(string)($_SESSION['last_order']??'');if(!$number){redirect('shop.php');}$q=$pdo->prepare('SELECT order_number,total,status,payment_status FROM orders WHERE order_number=?');$q->execute([$number]);$order=$q->fetch();unset($_SESSION['last_order']);site_header($pdo,'Order received'); ?><section class="empty-state success-page"><span class="eyebrow">ORDER RECEIVED</span><h1>Thank you.</h1><?php if($order): ?><p>Your order <b><?=e($order['order_number'])?></b> has been placed.</p><p>Total: <b><?=money((float)$order['total'])?></b></p><p>Status: <?=e($order['payment_status'])?> · <?=e($order['status'])?></p><p>Please contact the store to arrange payment.</p><?php endif; ?><a class="button" href="shop.php">CONTINUE SHOPPING</a></section><?php site_footer($pdo); ?>
